from pathlib import Path
import json, numpy as np, matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]; p=json.loads((ROOT/'reports/single_arm/held_out_test_results.json').read_text());d=p['robots'];out=ROOT/'reports/single_arm/figures'; robots=sorted(d,key=lambda r:d[r]['global']['pose_success_rate'],reverse=True)
pose=np.array([d[r]['global']['pose_success_rate'] for r in robots]); safe=np.array([d[r]['global']['success_rate'] for r in robots]); y=np.arange(len(robots));fig,ax=plt.subplots(figsize=(11,6));ax.barh(y+.18,100*pose,.34,label='Pose success');ax.barh(y-.18,100*safe,.34,label='Collision-aware safe success');ax.set(yticks=y,yticklabels=robots,xlim=(0,101),xlabel='Held-out success (%)');ax.invert_yaxis();ax.legend();fig.tight_layout();fig.savefig(out/'test_pose_and_safe_success.png',dpi=200);plt.close(fig)
reasons=('position','orientation','self_collision','table_collision'); matrix=np.array([[d[r]['global']['failure_counts'][x]/p['frame_count'] for x in reasons] for r in robots]);fig,ax=plt.subplots(figsize=(8,7));im=ax.imshow(100*matrix,aspect='auto',vmin=0,vmax=100,cmap='Reds');fig.colorbar(im,ax=ax,label='Affected frames (%)');ax.set(yticks=range(len(robots)),yticklabels=robots,xticks=range(4),xticklabels=('Position','Orientation','Self collision','Table collision'));plt.setp(ax.get_xticklabels(),rotation=25,ha='right');ax.set_title('Primary/secondary failure severity');fig.tight_layout();fig.savefig(out/'test_failure_reason_heatmap.png',dpi=200);plt.close(fig)
lines=['# Held-out test results','','500 frames from 25 test episodes, using per-model calibrated collision proxies and collision-aware branch selection.','','|Rank|Robot|Pose success|Safe success|Position RMSE|Orientation RMSE|','|---:|---|---:|---:|---:|---:|']
for i,r in enumerate(robots,1):g=d[r]['global'];lines.append(f"|{i}|{r}|{g['pose_success_rate']:.2%}|{g['success_rate']:.2%}|{1000*g['position_rmse_m']:.2f} mm|{g['orientation_rmse_rad']:.3f} rad|")
(ROOT/'reports/single_arm/HELD_OUT_RESULTS.md').write_text('\n'.join(lines),encoding='utf-8');print('\n'.join(lines))
